import{_ as r,o as n,c as t,ah as i}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse('{"title":"Recherche: Die modernen Machtzirkel der ÖVP","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/moderne-machtzirkel.md","filePath":"recherche/moderne-machtzirkel.md"}'),a={name:"recherche/moderne-machtzirkel.md"};function s(l,e,o,d,h,u){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="recherche-die-modernen-machtzirkel-der-ovp" tabindex="-1">Recherche: Die modernen Machtzirkel der ÖVP <a class="header-anchor" href="#recherche-die-modernen-machtzirkel-der-ovp" aria-label="Permalink to &quot;Recherche: Die modernen Machtzirkel der ÖVP&quot;">​</a></h1><p><strong>Vom „Neuen Stil“ zum Milliarden-Defizit: Die Fortsetzung des Pointillismus.</strong></p><p>In der modernen Phase des „Horten-Mysteriums“ begegnen uns Akteure, die das Erbe der diskreten Einflussnahme in das digitale Zeitalter übersetzt haben. Während Helmut Horten Kaufhäuser sammelte, sammelten diese Akteure Daten, Posten und – am Ende – ein gewaltiges Budgetloch.</p><hr><h2 id="die-schlusselfiguren" tabindex="-1">Die Schlüsselfiguren <a class="header-anchor" href="#die-schlusselfiguren" aria-label="Permalink to &quot;Die Schlüsselfiguren&quot;">​</a></h2><h3 id="_1-sebastian-kurz-gernot-blumel-die-architekten-des-„systems" tabindex="-1">1. Sebastian Kurz &amp; Gernot Blümel: Die Architekten des „Systems“ <a class="header-anchor" href="#_1-sebastian-kurz-gernot-blumel-die-architekten-des-„systems" aria-label="Permalink to &quot;1. Sebastian Kurz &amp; Gernot Blümel: Die Architekten des „Systems“&quot;">​</a></h3><ul><li><strong>Der Aufstieg:</strong> Mit dem „Projekt Ballhausplatz“ wurde die Machtübernahme in der ÖVP akribisch geplant.</li><li><strong>Die Methoden:</strong> Umfragen-Manipulation (Beinschab-Tool) und massive Inseratenkäufe in Boulevardmedien.</li><li><strong>Gernot Blümel:</strong> Als engster Vertrauter und Finanzminister geriet er durch die „Laptop-Affäre“ (Spaziergang mit dem Kinderwagen) und seine Gedächtnislücken im U-Ausschuss in die Schlagzeilen.</li></ul><h3 id="_2-magnus-brunner-der-verwalter-des-defizits" tabindex="-1">2. Magnus Brunner: Der Verwalter des Defizits <a class="header-anchor" href="#_2-magnus-brunner-der-verwalter-des-defizits" aria-label="Permalink to &quot;2. Magnus Brunner: Der Verwalter des Defizits&quot;">​</a></h3><ul><li><strong>Das „Budgetloch“:</strong> Unter Brunner explodierte das Staatsdefizit 2024 auf <strong>4,7 % des BIP</strong> – weit über der EU-Maastricht-Grenze von 3 %.</li><li><strong>Die Inflation:</strong> Österreich verzeichnete unter Brunner eine der höchsten Inflationsraten der Eurozone (2,9 % in 2024, Anstieg auf 3,6 % in 2025 nach Auslaufen der Strompreisbremse).</li><li><strong>Der Abgang:</strong> Ende 2024 wechselte Brunner als EU-Kommissar nach Brüssel, während in Österreich über die „geschönten“ Budgetprognosen debattiert wurde.</li></ul><h3 id="_3-wolfgang-sobotka-der-wachter-des-parlaments" tabindex="-1">3. Wolfgang Sobotka: Der Wächter des Parlaments <a class="header-anchor" href="#_3-wolfgang-sobotka-der-wachter-des-parlaments" aria-label="Permalink to &quot;3. Wolfgang Sobotka: Der Wächter des Parlaments&quot;">​</a></h3><ul><li><strong>Rolle:</strong> Als Nationalratspräsident leitete er die U-Ausschüsse, in denen die Korruptionsvorwürfe gegen seine eigene Partei behandelt wurden – ein permanenter Interessenkonflikt nach Ansicht der Opposition.</li><li><strong>Symbolik:</strong> Die „Sobotka-Orgel“ (ein teures Miet-Klavier im Parlament) wurde zum Symbol für eine abgehobene Machtelite, die sich den Luxus auf Steuerzahlerkosten gönnt, während die Inflation das Volk trifft.</li></ul><hr><h2 id="parallelen-zum-horten-erbe" tabindex="-1">Parallelen zum Horten-Erbe <a class="header-anchor" href="#parallelen-zum-horten-erbe" aria-label="Permalink to &quot;Parallelen zum Horten-Erbe&quot;">​</a></h2><p>In unserer Mockumentary ziehen wir folgende Linien:</p><ul><li><strong>Verschleierung:</strong> Was früher die Spendenstückelung bei Heidi Horten war, ist heute die Diskrepanz zwischen Budgetprognosen und Realität bei Magnus Brunner.</li><li><strong>Machtanspruch:</strong> Die „Marktbereinigung“ Helmut Hortens findet ihre moderne Entsprechung im „Postenschacher“ (August Wöginger) und der Kontrolle der Medienlandschaft.</li><li><strong>Aesthetic of Silence:</strong> Sobotka verkörpert den parlamentarischen Widerstand gegen die vollständige Aufklärung – das „Archiv des Schweigens“ in seiner modernsten Form.</li></ul><hr><p><em>Quellen: Berichte der Statistik Austria (2024/2025), WKStA-Ermittlungsakten, Analysen zum EU-Defizitverfahren gegen Österreich.</em></p>',17)])])}const m=r(a,[["render",s]]);export{g as __pageData,m as default};
